//! 🧪️ Recursive SELECT leaves retain exact public candidate and original context authority.
use super::*;
#[test]
fn original_leaf_cursor_matches_all_neutral_ordinals_without_allocating_and_rejects_substitute_root(){
 use super::super::super::type_input_select::{Cursor,Step};if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}let law=contract();let mut cursor=Cursor::default();let mut count=0;
 for turn in 0..100000{if turn>0{assert!(cursor.advance::<DetailsTestProfile>("IFCUNIT").is_err());}let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance::<DetailsTestProfile>("IFCVALUE"));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));match answer.unwrap(){Step::Pending=>{},Step::Leaf{index,name}=>{assert_eq!(index,count);assert_eq!(Some(name),law["members"][index].as_str());count+=1;},Step::Complete{count:actual}=>{assert_eq!(actual,count);break;}}assert!(turn<99999);}assert_eq!(count,109);
}
fn contract()->serde_json::Value{serde_json::from_str(include_str!("🧪️tests/type-value-select-input.json")).unwrap()}
fn value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"derived"=>IfcValue::Derived,"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"enum"=>IfcValue::Enum(row["value"].as_str().unwrap().into()),"binary"=>IfcValue::Binary(row["value"].as_str().unwrap().into()),"integer"=>IfcValue::Integer(row["value"].as_str().unwrap().parse().unwrap()),"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(value).collect()}),_=>panic!("closed original vector")}}
fn source(law:&serde_json::Value)->Arc<IfcSnapshot>{Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|row|IfcEntity{id:row["id"].as_str().unwrap().parse().unwrap(),name:row["name"].as_str().unwrap().into(),args:row["args"].as_array().unwrap().iter().map(value).collect(),complex:Vec::new()}).collect(),..Default::default()})}
fn payload(row:&serde_json::Value)->serde_json::Value{serde_json::json!({"kind":"typedValue","value":{"name":row["member"],"items":row["items"]}})}
fn with_prepared(law:&serde_json::Value,row:&serde_json::Value,check:impl FnOnce(&super::super::super::type_guidance::IfcPreparedTypeInputSource)){
 use semio_framework_plugin::action_staging::*;let snapshot=source(law);let editing::SnapshotEditEvent::SetValue{path,value}=event(law,row)else{unreachable!()};let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"original-value-binding".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::En,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:None});let mut caller=OriginalWorkFixture::new();let mut guide=Some(super::super::super::type_guidance::IfcTypeInputSourceWork::<DetailsTestProfile>::default());let mut output=None;assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());for turn in 0..1000000{if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());check(output.as_ref().unwrap());caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();
}
#[test]
fn original_recursive_binding_plans_keep_exact_carriers_and_closed_scalar_collection_addresses(){
 use semio_framework_plugin::{action_staging::*,app::staged_form::*};if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}let law=contract();for row in law["cases"].as_array().unwrap(){with_prepared(&law,row,|prepared|{assert_eq!(prepared.status().ready,row["domain"].as_bool().unwrap());let root=prepared.control(0).unwrap();if row["member"].is_null(){assert!(matches!(root.scalar.kind,StagedScalarKind::Choice{value:"",..}));return;}let StagedBodyBinding::Action(binding)=root.binding.unwrap()else{panic!("original leaf binding")};let chosen=DslValue::String(row["member"].as_str().unwrap().into());let StagedFormBorrowedEdit::Set{value,..}=binding.plan(prepared.status(),Some(&chosen)).unwrap().last().unwrap()else{panic!("exact typed payload")};assert_eq!(value,&super::type_input_tests::raw(&payload(row)));let child=prepared.control(1).unwrap();let StagedBodyBinding::Action(binding)=child.binding.unwrap()else{panic!("original child binding")};let items=row["items"].as_array().unwrap();match row["member"].as_str().unwrap(){"IFCBOOLEAN"|"IFCLOGICAL"=>{let selected=DslValue::String("T".into());let edit=binding.plan(prepared.status(),Some(&selected)).unwrap().last().unwrap();let(path,value)=match edit{StagedFormBorrowedEdit::Append{path,value}if items.is_empty()=>(path,value),StagedFormBorrowedEdit::Set{path,value}if !items.is_empty()=>(path,value),_=>panic!("explicit enum child")};assert_eq!(path.len(),if items.is_empty(){6}else{7});assert_eq!(value.get("kind").and_then(DslValue::as_str),Some("enum"));assert_eq!(value.get("value").and_then(DslValue::as_str),Some("T"));},"IFCCOMPOUNDPLANEANGLEMEASURE"=>{let StagedFormBorrowedEdit::Append{path,value}=binding.plan(prepared.status(),None).unwrap().last().unwrap()else{panic!("explicit LIST operation")};assert_eq!(path.len(),if items.is_empty(){6}else{8});assert_eq!(value.get("kind").and_then(DslValue::as_str),Some(if items.is_empty(){"aggregate"}else{"integer"}));if let Some(members)=items.first().and_then(|child|child["value"].as_array()){for(index,member)in members.iter().take(7).enumerate(){let control=prepared.control(2+index*2).unwrap();assert!(matches!(control.scalar.kind,StagedScalarKind::Text{value}if Some(value)==member["value"].as_str()));let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("exact integer Text binding")};let word=DslValue::String("-9".into());let StagedFormBorrowedEdit::Set{path,..}=binding.plan(prepared.status(),Some(&word)).unwrap().last().unwrap()else{panic!("integer member")};assert_eq!(path.len(),10);assert_eq!(path[8],index.to_string());}}},"IFCBINARY"=>{let word=DslValue::String("0A5FF".into());let StagedFormBorrowedEdit::Set{path,value}=binding.plan(prepared.status(),Some(&word)).unwrap().last().unwrap()else{panic!("typed BINARY exact text")};assert_eq!(path.len(),8);assert_eq!(value,&word);},_=>{}}});}
}
fn event(law:&serde_json::Value,row:&serde_json::Value)->editing::SnapshotEditEvent{editing::SnapshotEditEvent::SetValue{path:"/entities/0".into(),value:super::type_input_tests::raw(&serde_json::json!({"$ifcType":law["entity"],"$ifcInputs":if row["member"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":"0","value":payload(row)}])}}))}}
#[test]
fn original_recursive_kind_completes_the_whole_released_value_tree_without_heap_or_branch_selection(){
 use super::super::super::type_input_kind::{Cursor,Kind};if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}let attribute=DetailsTestProfile::normalization_attribute("IFCMEASUREWITHUNIT",0,true).unwrap().unwrap();let mut cursor=Cursor::default();let mut complete=None;for turn in 0..100000{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance::<DetailsTestProfile>(attribute.type_expr));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(kind)=answer.unwrap(){complete=Some(kind);assert!(turn>=109);break;}}assert_eq!(complete,Some(Kind::Select));assert_eq!(cursor.domain(),Some("IFCVALUE"));
}
#[test]
fn original_recursive_candidates_emit_only_actual_value_atoms_and_restore_the_exact_original_unit(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law);let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(&law,row),&mut caller,&mut work,|input,caller,work|{let mut result=None;for turn in 0..1000000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Ok(ArtifactCommandWorkStep::Complete(emit))=>{result=Some(Ok(emit));break;},Err(error)=>{result=Some(Err(error));break;},_=>{}}assert!(turn<999999);}let result=result.unwrap();assert_eq!(result.is_ok(),row["domain"]==true,"{}",row["id"]);if let Ok(emit)=result{assert_eq!(emit.artifact_mutations.len(),1);assert!(matches!(emit.artifact_mutations[0],IfcMutation::SetEntityArg(_)));let mutation=&emit.artifact_mutations[0];let inverse=mutation.inverse(&snapshot).unwrap();let mut next=protocol::apply_diff_cold(mutation.diff(&snapshot).diff(),&snapshot).unwrap();assert!(ifc_arguments_identical(&next.entities[0].args,&[value(&payload(row)),IfcValue::Reference(7)]));assert!(ifc_arguments_identical(&next.entities[1].args,&snapshot.entities[1].args));for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args,&snapshot.entities[0].args));assert!(ifc_arguments_identical(&next.entities[1].args,&snapshot.entities[1].args));}super::constituent_optional_shape_tests::close_with_denials(caller,work);});caller.finish();}
}
#[test]
fn original_recursive_donated_choice_pages_preserve_pinned_selected_value_and_every_denied_axis(){
 use semio_framework_plugin::{action_staging::*,app::staged_form::*};type Guidance=super::super::super::type_guidance::IfcTypeInputSourceWork<DetailsTestProfile>;
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}let law=contract();let row=law["cases"].as_array().unwrap().iter().find(|row|row["id"]=="last-page-unicode").unwrap();for page in law["pages"].as_array().unwrap(){let snapshot=source(&law);let editing::SnapshotEditEvent::SetValue{path,value}=event(&law,row)else{unreachable!()};let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"original-recursive-value".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::De,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:if page["offset"]=="0"{None}else{Some(StagedFormPage{field_offset:"0".into(),diagnostic_offset:"0".into(),choice:Some(StagedFormChoicePage{path:vec!["entities".into(),"0".into(),"args".into(),"0".into()],offset:page["offset"].as_str().unwrap().into()})})}});let mut caller=OriginalWorkFixture::new();let mut guide=Some(Guidance::default());let mut output=None;assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());for turn in 0..1000000{let demand=guide.as_ref().unwrap().demands().unwrap();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||guide.as_ref().unwrap().demands());assert_eq!(answer.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=guide.as_mut().unwrap().advance(&snapshot,[0;32],cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());let prepared=output.as_ref().unwrap();assert!(prepared.status().ready);let control=prepared.control(0).unwrap();let StagedScalarKind::Choice{value,choices}=control.scalar.kind else{panic!("actual leaf choices")};assert_eq!(value,"IFCURIREFERENCE");assert!(choices.len()<=32);let offset=page["offset"].as_str().unwrap().parse::<usize>().unwrap();let count=page["ordinary"].as_u64().unwrap()as usize;assert_eq!(choices[..count].iter().map(|choice|choice.key).collect::<Vec<_>>(),law["members"].as_array().unwrap()[offset..offset+count].iter().map(|name|name.as_str().unwrap()).collect::<Vec<_>>());assert!(choices.iter().any(|choice|choice.key=="IFCURIREFERENCE"));let control=prepared.control(1).unwrap();assert!(matches!(control.scalar.kind,StagedScalarKind::Text{value:"urn:caller:ä:€"}));caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();}
}
